import{_ as t,c as l,o as s,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"讀易舉要","description":"讀易舉要 - 讀易舉要","frontmatter":{"title":"讀易舉要","description":"讀易舉要 - 讀易舉要"},"headers":[],"relativePath":"classics/juyao/001.md","filePath":"classics/juyao/001.md"}'),r={name:"classics/juyao/001.md"};function o(c,a,i,p,d,u){return s(),l("div",null,[...a[0]||(a[0]=[e("h1",{id:"讀易舉要",tabindex:"-1"},[n("讀易舉要 "),e("a",{class:"header-anchor",href:"#讀易舉要","aria-label":"Permalink to “讀易舉要”"},"​")],-1),e("p",null,"欽定四庫全書經部一",-1),e("p",null,"易類提要",-1),e("p",null,"臣 等謹案：",-1),e("p",null,"讀易舉要四卷，宋俞琰撰。是書文淵閣書目、焦竑經籍志、朱睦桔授經圖皆著於錄。然外間傅本殊稀，故朱彝尊經義考亦云「未見」。今惟永樂大典尚散見於各韻之中，可以採輯。謹裒合編次，仍定為四卷。考琰之集說，以朱子為宗，而此書論剛柔往來，則以兩卦反對見義例，以泰、否二卦彖辭，較朱子卦變之說更近自然。其易圖多本邵子，而此書論象數之學，則駁張行成以「元亨利貞」為周易起數於四之證，蓋不為苟同者。至於田疇，謂積乾坤屯蒙、需、訟之策，至於師而六軍之數皆全。史璇謂革居四十九，應大衍之數，故云天地革而四時成；節居六十而甲子一週，故云天地節而四時成。皆以偶合之見，窺聖人作易之意。琰顧取之，則殊非本旨。然琰於易苦思力索，積平生之力為之，意所獨契，亦往往超出前人。所列諸家著述，雖多本於晁公武、陳振孫兩家，而名字爵裡間有異同，亦可資考證，固宜與所撰集說並行也。琰別有六十四卦圖、易圖合璧聯珠、易圖纂要諸書，舊與此書合刻。修永樂大典之時，割裂龐雜，淆其端緒。惟八分為十六，十六分為三十二兩圖猶標俞琰纂圖之目，其餘諸圖盡冒讀易舉要之名，合併為一，殊為瞀亂。今悉考訂汰除，以還其舊焉。乾隆四十六年九月恭校上。",-1),e("p",null,"總纂官 臣 紀昀、 臣 陸錫熊、 臣 孫士毅，總校官 臣 陸費墀。欽定四庫全書讀易舉要目錄：卷一易為卜筮之書卦畫取象佔用陰陽老少佔用貞悔卦爻之佔辭象佔所稱象辭佔辭之異卦變剛來柔來上下圖卷二易中雜例卦義八卦主爻圖十二卦主爻圖卦之主爻乘承比應辭韻之葉卷三論象數之學",-1),e("p",null,"河圖洛書之附會， 附圖三， 卦氣之附會納甲之附會三易易字義卦象彖爻字義重卦之人名卦之人作彖辭爻辭之人卷四，",-1),e("p",null,"經分上下二篇， 附圖三， 十翼之目古文周易十二篇漢儒相傳之易魏晉以後唐宋以來諸家著述",-1)])])}const f=t(r,[["render",o]]);export{_ as __pageData,f as default};
